def nxt(s):
    r=''
    for ch,d in zip(s,(3,-4,5)):
        r+=chr((ord(ch)-65+d)%26+65)
    return r
seq=['HPL','KLQ','NHV','QDA','TZF']
assert all(nxt(seq[i])==seq[i+1] for i in range(4))
ans=nxt('TZF')
opts={'A':'WVK','B':'XVK','C':'WDK','D':'XWK'}
assert ans==opts['A'] and all(ans!=opts[k] for k in 'BCD')

