tmpl='E_GH'+'EI_G'+'ELK_'+'_OME'
def fill(s):
    it=iter(s);return ''.join(next(it) if c=='_' else c for c in tmpl)
def ok(w):
    b=[w[i:i+4] for i in range(0,16,4)]
    return all(x[0]=='E' for x in b) and all(ord(b[i+1][1])-ord(b[i][1])==3 for i in range(3)) and all(ord(b[i+1][2])-ord(b[i][2])==2 for i in range(3)) and all(ord(b[i+1][3])-ord(b[i][3])==-1 for i in range(3))
assert [k for k,v in opts.items() if ok(fill(v))]==['C']

